public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int length = 1; length <= strings.get(0).length(); length++) {
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i <= strings.get(0).length() - length; i++) {
            substrings.add(strings.get(0).substring(i, i + length));
        }

        boolean valid = true;
        for (String substring : substrings) {
            String reversed = new StringBuilder(substring).reverse().toString();
            boolean found = false;
            for (String str : strings) {
                if (str.contains(substring) || str.contains(reversed)) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                valid = false;
                break;
            }
        }

        if (valid) {
            maxLength = length;
        }
    }

    return maxLength;
}

