public boolean hasAllCodes(String s, int k) {
    int need = 1 << k;
    int allOne = need - 1;
    boolean[] got = new boolean[need];
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal << 1) & allOne) | (s.charAt(i) - '0');
        if (i >= k - 1 && !got[hashVal]) {
            got[hashVal] = true;
            need--;
            if (need == 0) {
                return true;
            }
        }
    }
    return false;
}

