public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close > 0) {
                insertions += open < close ? open : close;
                open = Math.max(open - close, 0);
                close = 0;
            }
            open++;
        } else if (c == ')') {
            close++;
            if (open == 0) {
                insertions++;
            } else {
                open--;
            }
        }
    }

    if (close > 0) {
        insertions += open < close ? open : close;
        open = Math.max(open - close, 0);
        close = 0;
    }

    return insertions + open + close;
}

