public int minInsertions(String s) {
    int openNeeds = 0; // To track the need for '('
    int closeNeeds = 0; // To track the need for ')'
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            openNeeds++;
            i++;
            // Check for "())" pattern
            if (i < s.length() && s.charAt(i) == ')') {
                i++;
            } else {
                closeNeeds++; // Need one more ')' to pair with '('
            }
        } else { // s.charAt(i) == ')'
            if (openNeeds > 0) {
                openNeeds--; // Pair with an existing '('
            } else {
                closeNeeds++; // Need one more '(' to pair with this ')'
            }
            i++;
        }
    }

    // Total insertions needed is the sum of unpaired '(' and ')'
    return openNeeds + closeNeeds;
}

