public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < n) {
        int remaining = n - i - 1;
        int minPossibleValue = remaining * 26;
        int val = Math.max(1, k - minPossibleValue);
        result.append((char)(val + 'a' - 1));
        k -= val;
        i++;
    }
    return result.toString();
}

