        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                count++;
                maxLine = Math.max(maxLine, count);
            } else {
                count = 0;
            }
        }
    }

    // Diagonal
    for (int k = -m + 1; k < n; k++) {
        int count = 0;
        for (int j = Math.max(k, 0); j < n && j - k < m; j++) {
            if (mat[j - k][j] == 1) {
                count++;
                maxLine = Math.max(maxLine, count);
            } else {
                count = 0;
            }
        }
    }

    // Anti-diagonal
    for (int k = 0; k < m + n - 1; k++) {
        int count = 0;
        for (int j = Math.max(k - m + 1, 0); j < n && k - j < m; j++) {
            if (mat[k - j][j] == 1) {
                count++;
                maxLine = Math.max(maxLine, count);
            } else {
                count = 0;
            }
        }
    }

    return maxLine;
}

